      "content": "{\n  \"name\": \"dsh-eye-comfort\",\n  \"version\": \"0.3.22\",\n  \"description\": \"Eye-comfort appearance controls for DeepSeek Harness: five light and five dark themes, themed syntax and diff colours, scheduled switching, JSON import/export, paper-grain texture, fonts, type sizes, content width and contrast.\",\n  \"keywords\": [\"deepseek-harness\", \"dsh-plugin\", \"theme\", \"appearance\"],\n  \"license\": \"MIT\",\n  \"repository\": {\"type\": \"git\", \"url\": \"git+https://github.com/AaronKate/dsh-codex-appearance.git\"},\n  \"homepage\": \"https://github.com/AaronKate/dsh-codex-appearance\",\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"exports\": {\".\": \"./lib/index.js\", \"./client\": \"./lib/client.js\", \"./cordis.patch.yml\": \"./cordis.patch.yml\"},\n  \"files\": [\"lib\", \"cordis.patch.yml\", \"README.md\"],\n  \"dsh\": {\n    \"meta\": {\n      \"title\": {\"en\": \"Eye Comfort\", \"zh\": \"护眼外观\"},\n      \"description\": {\n        \"en\": \"Adjust the DeepSeek Harness UI: five light and five dark themes, themed syntax highlighting and diff colours, scheduled switching, JSON import/export, fonts, type sizes, content width and contrast.\",\n        \"zh\": \"调整 DeepSeek Harness 的界面外观：五套浅色与五套深色主题、语法高亮与 diff 配色、定时切换、设置导入导出、字体字号、内容宽度、对比度与动态效果。\"\n      }\n    },\n    \"bundle\": {\"patch\": \"./cordis.patch.yml\"},\n    \"client\": {\"inject\": [\"@deepseek-ai/dsh-client-ui-theme\", \"@deepseek-ai/dsh-client-ui-settings-general\", \"@deepseek-ai/dsh-client-ui-renderer\"], \"platform\": \"web\"}\n  },\n  \"engines\": {\"node\": \">=22.19\"}\n}\n"
